19	      xrButton.setProperties({ display: 'none' });
20	      exitButton.setProperties({ display: 'none' });
21	      return;
22	    }
23	
24	    const launchXR = () => this.world.launchXR();
25	    const exitXR = () => this.world.exitXR();
26	    xrButton.addEventListener('click', launchXR);
27	    exitButton.addEventListener('click', exitXR);
28	    this.cleanupFuncs.push(
29	      () => xrButton.removeEventListener('click', launchXR),
30	      () => exitButton.removeEventListener('click', exitXR),
31	      this.world.visibilityState.subscribe((visibilityState) => {
32	        const is2D = visibilityState === VisibilityState.NonImmersive;
33	        xrButton.setProperties({ display: is2D ? 'flex' : 'none' });
